L.GUIDE_PAGE4_TITLE         = "Command & rankings"
L.GUIDE_SECTION_PANEL       = "The Overlord panel"
L.GUIDE_PANEL_BODY          = "Open the |cFFFFD100|Haddon:Overlord:panel|hOverlord panel|h|r from the minimap button or the DataBroker icon.\n\n|cFFFFFFFFOn the panel|r\n• |cFFFFD100Weekly domination|r: territory share between Alliance and Horde this week.\n• |cFFFFD100Recent activity|r: fighting reported during the last 5 minutes across every front and the Coiled Isle.\n• |cFFFFD100Actions|r: Leaderboard, Community, Contracts, Export, Discord, Hall of Fame, Tutorial, front picker, Call to arms, Command, and Options.\n• |cFFFFD100Front selector|r: Arathi, Gilneas, Loch Modan, Southern Barrens, Durotar, and Elwynn Forest.\n• |cFFFFD100Arrow tab|r (left edge): featured front of the day, control zones, and open contracts.\n\n|cFFFFFFFFOn screen|r\n• Top HUD: coins, wood, guild keep (if applicable), |cFFFFD100Next objective|r arrow.\n• Book icon: reopens this guide anytime."
L.GUIDE_SECTION_OPTIONS     = "Useful options"
L.GUIDE_OPTIONS_BODY        = "Open |cFFFFD100Options|r on the panel, or |cFFFFD100Escape → AddOns → Overlord|r.\n\n• |cFFFFD100Automatic objective pin|r: places the Blizzard map pin on the next objective (on by default; waits if you remove it).\n• |cFFFFD100Top HUD|r: hide the coins, wood, tutorial and guild keep bar while keeping the |cFFFFD100Next objective|r indicator.\n• |cFFFFD100Overlord sounds|r: mute alerts, war horn, captures and panel sounds.\n• |cFFFFD100Map overlays|r: adjust capture opacity on the world map and minimap, plus path line visibility.\n• |cFFFFD100Panel scale|r: resize the main panel and leaderboard (or |cFFFFD100/ov scale|r).\n\nType |cFFFFD100/ov guide|r anytime to reopen this tutorial."
L.GUIDE_SECTION_FEATURED    = "Featured front of the day"
L.GUIDE_FEATURED_BODY       = "Each siege day, one front is featured. On that front in War Mode, each honorable kill grants |cFFFFD100+1 Overlord coin|r.\n\nThe side panel shows the |cFFFFD100most recent fighting|r reported on every front during the last 5 minutes (validated sync data: kills, captures, zones under assault).\n\nWhen gold contracts are open, it also shows an |cFFFFD100Open contracts|r shortcut."
L.GUIDE_SECTION_CONTEST     = "Contested captures"
L.GUIDE_CONTEST_BODY        = "Normal zones need |cFFFFD1002:00|r inside the capture circle. Stand in the circle to progress the timer. Leaving the zone makes progress |cFFFF4444decay|r.\n\nEnemy players inside |cFFFF4444contest|r the capture: even headcount freezes the timer; enemy superiority makes it fall back until you regain the advantage."
L.GUIDE_SECTION_HOF         = "Hall of Fame"
L.GUIDE_HOF_BODY            = "Curated |cFFFFD100guild and player honors|r from the war fronts (weekly feats, regiment tributes, lifetime stats, etc.).\n\nOpen it from |cFFFFD100Actions|r on the panel. Entries are hand-picked; not every honor appears on the world map."
L.GUIDE_SECTION_TOOLS       = "Rankings & sync"
L.GUIDE_TOOLS_BODY          = "• |cFFFFD100Leaderboard|r: weekly kills, captures, guild keeps, and outposts for synced players.\n• |cFFFFD100Community|r: join the Overlord community roster for better sync and invites.\n• |cFFFFD100Export|r: copy your stats for |cFFFFD100Check PvP|r.\n• |cFFFFD100Statistics|r: extra Overlord tab on your character sheet.\n\nStay grouped on the |cFFFFD100same shard|r for reliable state updates."
L.GUIDE_SECTION_TRAVEL      = "Getting there"
L.GUIDE_TRAVEL_ALLIANCE     = "Enable |cFFFFD100War Mode|r (Talents, N key). Required for Overlord."
L.GUIDE_TRAVEL_HORDE        = "Enable |cFFFFD100War Mode|r (Talents, N key). Required for Overlord."
L.GUIDE_SECTION_SHARD       = "Shards & realms"
L.GUIDE_SHARD_BODY          = "|cFFFFD100Normal|r and |cFFFFD100Roleplay|r realms are on |cFFFFD100separate shards|r by default. You will not see each other in the open world unless you phase together.\n\n|cFFFFFFFFFor the best experience|r\n• |cFFFFD100Group up|r (party or raid) with allies on the |cFFFFD100same shard|r. The addon shows your shard ID on the panel badge; click it to invite players on a different layer."
L.GUIDE_SECTION_PROGRESS    = "War fronts"
L.GUIDE_PROGRESS_BODY       = "Six independent |cFFFFD100war fronts|r: Arathi Highlands, Gilneas, Loch Modan, Southern Barrens, Durotar, and Elwynn Forest. Each has its own zone tree and faction capital.\n\nZones marked |cFFFFD100AVAILABLE|r on the map can be attacked once their prerequisites are held. There may be |cFFFFD100several at once|r on parallel branches.\n\nThe |cFFFFD100Next objective|r HUD points to the nearest zone. Check the map for other options."
L.GUIDE_SECTION_GOLD        = "Coin mines"
L.GUIDE_GOLD_BODY           = "Coin mine circles on the world map:\n%s\n\nWar Mode required.\n\n|cFFFFFFFFHow to earn coins|r\n• |cFFFFD100Passive|r: +1 coin every 3 s while inside the circle (cap 100).\n• |cFFFFD100Mining|r: +5 coins per ore node mined inside the circle.\n\n|cFFFFFFFFSpend coins (25 coins)|r\n• |cFFFFD100Attack|r: your next zone, capital, outpost, or Guild Keep capture finishes 60 s sooner.\n• |cFFFFD100Reinforce|r: the next enemy capture on your zones lasts 60 s longer.\n\nAn enemy mining in your mine alerts your whole faction."
L.GUIDE_SECTION_WOOD        = "Forests"
L.GUIDE_WOOD_BODY           = "Forest circles on the world map:\n%s\n\nWar Mode required.\n\n|cFFFFFFFFHow to earn wood|r\n• |cFFFFD100Passive|r: +1 wood every 15 s while inside the circle (personal cap 500).\n• |cFFFFD100Shared reserves|r: each forest has faction-wide reserves (100); depleted reserves refill over time.\n\n|cFFFFFFFFSpend wood (250 wood)|r\n• |cFFFFD100Domination +1%|r: invest personal wood to boost your faction's weekly domination.\n\nForest reserves sync between Overlord users."
L.GUIDE_SECTION_SIEGE       = "Capital siege"
L.GUIDE_SIEGE_BODY          = "Enemy capitals use a single |cFFFFD1008:00|r capture timer (your own capital recaptures in |cFFFFD1002:00|r like a normal zone).\n\n|cFFFFD10015 min truce|r after a total front victory (+2% weekly domination for the winner)."
L.GUIDE_SECTION_OUTPOST     = "Guild outposts"
L.GUIDE_OUTPOST_BODY        = "One |cFFFFD100guild outpost|r per war front map, plus the temporary outdoor outpost on the Coiled Isle (always open, unlike guild keeps).\n\n|cFFFFFFFFRules|r\n• |cFFFFD100War Mode|r and a |cFFFFD100guild|r required to assault.\n• Hold the square for |cFFFFD1005 min|r; leaving makes progress |cFFFF4444decay|r.\n• Only the |cFFFFD100enemy faction|r can contest or reclaim.\n• An enemy assault can begin |cFFFFD100immediately after capture|r.\n• While held, enemy captures on normal points in that front take |cFFFF444430 sec longer|r.\n• It remains with its guild until an enemy capture or the weekly reset.\n\nAssault and capture alerts appear in chat. The outpost is shown on the world map and tracked in the leaderboard."
L.GUIDE_SECTION_GENERAL     = "War General"
L.GUIDE_GENERAL_BODY        = "The |cFFFFD100Command|r button (raid or party leader, Overlord community required) lets you assume the banner. Your icon appears on the war map for all synced allies.\n\nOne general per faction on the active front. Click again to relinquish command."
L.GUIDE_SECTION_BOUNTY      = "Blood bounty"
L.GUIDE_BOUNTY_BODY         = "Reach |cFFFFD10010 kills|r without dying on a war front and you become a |cFFFFD100blood bounty|r. Your skull icon shows on the map for enemies.\n\nClaiming a blood bounty grants |cFFFFD100+1 bonus kill|r and |cFFFFD100+25 coins|r to the hunter."
L.GUIDE_SECTION_GOLD_CONTRACT = "Gold contracts"
L.GUIDE_GOLD_CONTRACT_BODY  = "Sign personal |cFFFFD100gold contracts|r on enemy players via the |cFFFFD100Contracts|r button on the war panel.\n\n|cFFFFFFFFHow it works|r\n• Pick a known enemy from your |cFFFFD100Connected Realm group|r or any enemy character in your |cFFFFD100Overlord communities|r.\n• You must be on an |cFFFFD100active war front|r to sign a contract.\n• Several players can offer separate rewards on the same target.\n• Each killing blow claims only the highest compatible reward; the others remain open.\n• The hunter who lands the |cFFFFD100killing blow|r on any Overlord war front |cFFFFD100claims|r the contract automatically.\n\n|cFFFFFFFFPayment|r\nGold is |cFFFF4444not reserved|r. After claim convergence, the signer verifies and authorizes the winner. The approved hunter sends a |cFFFFD100verified COD invoice|r with one worthless item. The signer accepts it manually in Blizzard's mailbox. Direct outgoing gold mail remains available as a fallback. The hunter and signer must belong to the same Connected Realm group.\n\n|cFFFFFFFFOn the map|r\nActive contract targets show a |cFFFFD100wax seal|r on zone, continent, and minimap maps.\n\nA player with an open contract on them cannot assume the |cFFFFD100General|r role."
L.GUIDE_SECTION_FACTION_CALL = "Faction call"
L.GUIDE_FACTION_CALL_BODY   = "The |cFFFFD100Call to arms|r button (on an active front, with nearby enemies) alerts online allies in your |cFFFFD100Overlord community|r. Shared cooldown across the faction banner."
L.VICTORY_DOMINATION_BONUS  = "Total front victory: +%d%% weekly domination for your faction."
L.GUIDE_SECTION_GUILD_KEEP  = "Guild Keep"
L.GUIDE_GUILD_KEEP_BODY     = "Separate from the six |cFFFFD100war fronts|r (Arathi, Gilneas, Loch Modan, Southern Barrens, Durotar, Elwynn Forest): guild keeps on |cFFFFD100Ashenvale|r, |cFFFFD100The Wetlands|r, |cFFFFD100Badlands|r, |cFFFFD100The Crossroads|r, |cFFFFD100Redridge Mountains|r, and |cFFFFD100Mulgore|r.\n\n|cFFFFFFFFKeep icons|r\n%s\n\n|cFFFFFFFFRules|r\n• |cFFFFD100War Mode|r active and |cFFFFD100guild|r required.\n• Keeps are vulnerable every 6 hours at |cFFFFD100%s|r.\n• Outside this window, capture is closed.\n\n|cFFFFFFFFCapture|r\n• |cFFFFD100%d min|r inside the square: leave it and progress |cFFFF4444decays|r.\n• Enemy bodies in the square |cFFFF4444contest|r the keep: even numbers freeze progress, enemy superiority makes it fall back.\n• Only the |cFFFFD100enemy faction|r can contest or reclaim the keep.\n• The central capture timer appears only for your guild's assailants inside the square.\n• |cFFFFD100Leaderboard kills|r on a keep count only during the siege hour and only inside the capture square.\n• Progress syncs between addon users (GK): stay grouped for faster updates.\n\n|cFFFFFFFFVictory at %s|r\n• Capture or defense counts the same: |cFFFFD1001 win per siege|r for that keep.\n• A held keep stays yours until weekly reset or an enemy guild captures it during a siege.\n• Ranking shows only the current holder and siege wins."
L.TOOLTIP_SHIFT_GUIDE       = "Shift + left click: Quick guide"

