L.GUIDE_PANEL_BODY          = "Ouvrez le |cFFFFD100|Haddon:Overlord:panel|hpanneau Overlord|h|r via le bouton minimap ou l'icône DataBroker.\n\n|cFFFFFFFFSur le panneau|r\n• |cFFFFD100Domination hebdo|r : part des territoires Alliance / Horde cette semaine.\n• |cFFFFD100Activité récente|r : combats signalés pendant les 5 dernières minutes sur chaque front et l'Île Annelée.\n• |cFFFFD100Actions|r : Classement, Communauté, Contrats, Export, Discord, Hall of Fame, Tutoriel, sélecteur de front, Aux armes, Commandement et Options.\n• |cFFFFD100Sélecteur de front|r : Arathi, Gilnéas, Loch Modan, Tarides du Sud, Durotar et Forêt d'Elwynn.\n• |cFFFFD100Onglet flèche|r (bord gauche) : front du jour, zones de contrôle et contrats en cours.\n\n|cFFFFFFFFÀ l'écran|r\n• HUD haut : coins, bois, fortin de guilde (le cas échéant), flèche |cFFFFD100Prochain objectif|r.\n• Icône livre : rouvre ce guide à tout moment."
L.GUIDE_SECTION_OPTIONS     = "Options utiles"
L.GUIDE_OPTIONS_BODY        = "Ouvrez |cFFFFD100Options|r sur le panneau, ou |cFFFFD100Échap → AddOns → Overlord|r.\n\n• |cFFFFD100Repère automatique d'objectif|r: place le repère Blizzard sur le prochain objectif (activé par défaut ; Overlord attend si vous le retirez).\n• |cFFFFD100HUD du haut|r: masque les panneaux coins, bois, tutoriel et fortin de guilde tout en gardant l'indicateur |cFFFFD100Prochain objectif|r.\n• |cFFFFD100Sons Overlord|r: coupe alertes, cor de guerre, captures et sons de panneaux.\n• |cFFFFD100Overlays carte|r: opacité des captures sur la carte du monde et la minimap, plus visibilité des pointillés entre zones.\n• |cFFFFD100Échelle du panneau|r: taille du panneau principal et du classement (ou |cFFFFD100/ov scale|r).\n\nTapez |cFFFFD100/ov guide|r à tout moment pour rouvrir ce tutoriel."
L.GUIDE_SECTION_FEATURED    = "Front du jour"
L.GUIDE_FEATURED_BODY       = "Chaque jour de siège, un front est mis à l'honneur. Sur ce front en Mode Guerre, chaque victoire honorable donne |cFFFFD100+1 coin Overlord|r.\n\nLe panneau latéral affiche le |cFFFFD100combat le plus récent|r signalé sur chaque front pendant les 5 dernières minutes (données de sync validées : kills, captures, zones en prise).\n\nDes contrats en or ouverts y ajoutent aussi le raccourci |cFFFFD100Contrats en cours|r."
L.GUIDE_SECTION_CONTEST     = "Captures contestées"
L.GUIDE_CONTEST_BODY        = "Les zones normales demandent |cFFFFD1002:00|r dans le cercle de capture. Restez dans le cercle pour faire avancer le timer. Quitter la zone fait |cFFFF4444décroître|r la progression.\n\nDes ennemis à l'intérieur |cFFFF4444contestent|r la capture : égalité fige le timer ; surnombre ennemi le fait redescendre jusqu'à reprendre l'avantage."
L.GUIDE_SECTION_HOF         = "Hall of Fame"
L.GUIDE_HOF_BODY            = "|cFFFFD100Hommages guilde et joueurs|r curatés des fronts (exploits hebdo, régiments, stats carrière, etc.).\n\nAccessible via |cFFFFD100Actions|r sur le panneau. Entrées choisies à la main : tous les hommages n'apparaissent pas sur la carte du monde."
L.GUIDE_SECTION_TOOLS       = "Classements et sync"
L.GUIDE_TOOLS_BODY          = "• |cFFFFD100Classement|r : kills, captures, fortins et avant-postes hebdo des joueurs synchronisés.\n• |cFFFFD100Communauté|r : rejoignez la communauté Overlord pour une meilleure sync et des invitations.\n• |cFFFFD100Export|r : copiez vos stats pour |cFFFFD100Check PvP|r.\n• |cFFFFD100Statistiques|r : onglet Overlord sur la feuille de personnage.\n\nRestez groupés sur le |cFFFFD100même shard|r pour un état fiable."
L.GUIDE_SECTION_TRAVEL      = "S'y rendre"
L.GUIDE_TRAVEL_ALLIANCE     = "Activez le |cFFFFD100mode Guerre|r (talents, touche N). Indispensable pour Overlord."
L.GUIDE_TRAVEL_HORDE        = "Activez le |cFFFFD100mode Guerre|r (talents, touche N). Indispensable pour Overlord."
L.GUIDE_SECTION_SHARD       = "Shards et royaumes"
L.GUIDE_SHARD_BODY          = "Les serveurs |cFFFFD100Normal|r et |cFFFFD100Roleplay|r sont sur des |cFFFFD100shards séparés|r par défaut. Vous ne vous verrez pas dans le monde ouvert sans vous phaser ensemble.\n\n|cFFFFFFFFPour une meilleure expérience|r\n• |cFFFFD100Groupez-vous|r (groupe ou raid) avec vos alliés sur le |cFFFFD100même shard|r. L'addon affiche votre ID de shard sur le badge du panneau ; cliquez dessus pour inviter des joueurs sur une autre couche."
L.GUIDE_SECTION_PROGRESS    = "Fronts de guerre"
L.GUIDE_PROGRESS_BODY       = "Six |cFFFFD100fronts de guerre|r indépendants : Arathi, Gilnéas, Loch Modan, Tarides du Sud, Durotar et Forêt d'Elwynn. Chacun a son arbre de zones et sa capitale de faction.\n\nLes zones |cFFFFD100DISPONIBLE|r sur la carte sont attaquables une fois leurs prérequis tenus. Il peut y en avoir |cFFFFD100plusieurs en parallèle|r sur des branches distinctes.\n\nLe HUD |cFFFFD100Prochain objectif|r cible la zone la plus proche. Consultez la carte pour les autres options."
L.GUIDE_SECTION_GOLD        = "Mines de coins"
L.GUIDE_GOLD_BODY           = "Cercles sur la carte :\n%s\n\nMode Guerre obligatoire.\n\n|cFFFFFFFFComment gagner des coins|r\n• |cFFFFD100Gain sur place|r: +1 coin toutes les 3 s dans le cercle (plafond 100).\n• |cFFFFD100Minage|r: +5 coins à chaque extraction de minerai dans le cercle.\n\n|cFFFFFFFFDépenser les coins (25 coins)|r\n• |cFFFFD100Attaquer|r: votre prochaine capture de zone, capitale, avant-poste ou fortin se termine 60 s plus tôt.\n• |cFFFFD100Renforcer|r: la prochaine capture ennemie sur vos zones dure 60 s de plus.\n\nUn ennemi qui mine dans votre mine alerte toute votre faction."
L.GUIDE_SECTION_WOOD        = "Forêts"
L.GUIDE_WOOD_BODY           = "Cercles sur la carte :\n%s\n\nMode Guerre obligatoire.\n\n|cFFFFFFFFComment gagner du bois|r\n• |cFFFFD100Gain sur place|r: +1 bois toutes les 15 s dans le cercle (plafond personnel 500).\n• |cFFFFD100Réserves partagées|r: chaque forêt a des réserves de faction (100) ; une forêt épuisée se reconstitue avec le temps.\n\n|cFFFFFFFFDépenser le bois (250 bois)|r\n• |cFFFFD100Domination +1 %|r: investissez votre bois personnel pour booster la domination hebdo de votre faction.\n\nLes réserves se synchronisent entre joueurs Overlord."
L.GUIDE_SECTION_SIEGE       = "Siège des capitales"
L.GUIDE_SIEGE_BODY          = "Les capitales ennemies : un seul timer de |cFFFFD1008:00|r (recapture de votre capitale en |cFFFFD1002:00|r, comme une zone normale).\n\n|cFFFFD100Trêve de 15 min|r après une victoire totale du front (+2 %% de domination hebdo pour le gagnant)."
L.GUIDE_SECTION_OUTPOST     = "Avant-postes de guilde"
L.GUIDE_OUTPOST_BODY        = "Un |cFFFFD100avant-poste de guilde|r par carte de front, plus l'avant-poste extérieur temporaire sur l'Île Annelée (toujours ouvert, contrairement aux fortins).\n\n|cFFFFFFFFRègles|r\n• |cFFFFD100Mode Guerre|r et |cFFFFD100guilde|r requis pour assaillir.\n• Tenez le carré |cFFFFD1005 min|r ; en sortir fait |cFFFF4444décroître|r la progression.\n• Seule la |cFFFFD100faction ennemie|r peut contester ou reprendre.\n• Un assaut ennemi peut commencer |cFFFFD100dès la capture terminée|r.\n• Tant qu'il est tenu, les captures ennemies des points normaux de ce front durent |cFFFF444430 s de plus|r.\n• Il reste à sa guilde jusqu'à une capture ennemie ou au reset hebdomadaire.\n\nLes alertes d'assaut et de capture apparaissent dans le chat. L'avant-poste est visible sur la carte et suivi au classement."
L.GUIDE_SECTION_GENERAL     = "Général de guerre"
L.GUIDE_GENERAL_BODY        = "Le bouton |cFFFFD100Commandement|r (chef de groupe ou raid, communauté Overlord requise) permet de prendre la bannière. Votre icône apparaît sur la carte de guerre pour tous les alliés synchronisés.\n\nUn général par faction sur le front actif. Cliquez à nouveau pour abandonner le commandement."
L.GUIDE_SECTION_BOUNTY      = "Prime de sang"
L.GUIDE_BOUNTY_BODY         = "Atteignez |cFFFFD10010 kills|r sans mourir sur un front : vous devenez une |cFFFFD100prime de sang|r. Votre crâne apparaît sur la carte pour les ennemis.\n\nAbattre une prime de sang donne |cFFFFD100+1 kill bonus|r et |cFFFFD100+25 coins|r au chasseur."
L.GUIDE_SECTION_GOLD_CONTRACT = "Contrats en or"
L.GUIDE_GOLD_CONTRACT_BODY  = "Signez des |cFFFFD100contrats en or|r sur des joueurs ennemis via le bouton |cFFFFD100Contrats|r du panneau de guerre.\n\n|cFFFFFFFFFonctionnement|r\n• Choisissez un ennemi connu de votre |cFFFFD100groupe de royaumes connectés|r ou n'importe quel personnage ennemi de vos |cFFFFD100communautés Overlord|r.\n• Vous devez être sur un |cFFFFD100front de guerre actif|r pour signer un contrat.\n• Plusieurs joueurs peuvent proposer des récompenses distinctes sur la même cible.\n• Chaque coup de grâce ne réclame que la plus grosse prime compatible ; les autres restent ouvertes.\n• Le chasseur qui porte le |cFFFFD100coup de grâce|r sur n'importe quel front de guerre Overlord |cFFFFD100réclame|r le contrat automatiquement.\n\n|cFFFFFFFFPaiement|r\nL'or n'est |cFFFF4444pas réservé|r. Après convergence du claim, le signataire vérifie et autorise le gagnant. Le chasseur approuvé envoie une |cFFFFD100facture COD vérifiée|r avec un objet sans valeur. Le signataire l'accepte manuellement dans la boîte Blizzard. Le courrier d'or direct reste disponible en secours. Les deux personnages doivent appartenir au même groupe de royaumes connectés.\n\n|cFFFFFFFFSur la carte|r\nLes cibles sous contrat actif affichent un |cFFFFD100sceau de cire|r sur les cartes de zone, continent et minimap.\n\nUn joueur visé par un contrat ouvert ne peut pas prendre le rôle de |cFFFFD100Général|r."
L.GUIDE_SECTION_FACTION_CALL = "Appel de faction"
L.GUIDE_FACTION_CALL_BODY   = "Le bouton |cFFFFD100Aux armes|r (sur un front actif, avec des ennemis proches) alerte les alliés en ligne de votre |cFFFFD100communauté Overlord|r. Cooldown partagé pour toute la bannière."
L.VICTORY_DOMINATION_BONUS  = "Victoire totale: +%d %% de domination hebdomadaire pour votre faction."
L.GUIDE_SECTION_GUILD_KEEP  = "Fortin de guilde"
L.GUIDE_GUILD_KEEP_BODY     = "Hors des six |cFFFFD100fronts de guerre|r (Arathi, Gilnéas, Loch Modan, Tarides du Sud, Durotar, Forêt d'Elwynn) : fortins de guilde en |cFFFFD100Orneval|r, aux |cFFFFD100Paluns|r, aux |cFFFFD100Terres ingrates|r, à |cFFFFD100La Croisée|r, dans les |cFFFFD100Carmines|r et au |cFFFFD100Mulgore|r.\n\n|cFFFFFFFFIcônes de fortin|r\n%s\n\n|cFFFFFFFFRègles|r\n• |cFFFFD100Mode Guerre|r actif et |cFFFFD100guilde|r requis.\n• Les fortins sont vulnérables toutes les 6 heures : |cFFFFD100%s|r.\n• Hors de cette fenêtre, la capture est fermée.\n\n|cFFFFFFFFCapture|r\n• |cFFFFD100%d min|r dans le carré : en sortir fait |cFFFF4444redescendre|r le timer.\n• Des ennemis dans le carré |cFFFF4444contestent|r le fortin : égalité gèle la progression, surnombre ennemi la fait redescendre.\n• Seule la |cFFFFD100faction ennemie|r peut contester ou reprendre le fortin.\n• Le timer central n'apparaît que pour les assaillants de votre guilde dans le carré.\n• Les |cFFFFD100kills au classement|r sur un fortin ne comptent que pendant l'heure de siège, dans le carré.\n• La progression se synchronise entre joueurs Overlord (GK) : restez groupés.\n\n|cFFFFFFFFVictoire à %s|r\n• Capture ou défense comptent pareil : |cFFFFD1001 victoire par siège|r pour ce fortin.\n• Un fortin tenu reste à vous jusqu'au reset hebdo ou une capture ennemie pendant un siège.\n• Le classement affiche seulement le tenant actuel et les victoires."
L.TOOLTIP_SHIFT_GUIDE       = "Maj + clic gauche : guide rapide"
L.LOCKED            = "Verrouillée"

