L.FACTION_TALKING_HEAD_THRALL_NAME = "Thrall"
L.FACTION_TALKING_HEAD_THRALL_TEXT = "%s arde. Los espíritus traen los gritos de al menos %d combatientes.\n\n¡Lok'tar ogar! ¡Por la Horda!"
L.UI_SCALE_LABEL    = "Escala del panel"
L.UI_SCALE_TOOLTIP  = "Tamaño del panel principal y de la clasificación. También puedes usar |cffffffff/ov scale|r."
L.NOTIFICATION_CHAT_LABEL   = "Pestaña de chat de notificaciones"
L.NOTIFICATION_CHAT_TOOLTIP = "Destino de los mensajes de estado de Overlord (alertas, entrada/salida de zona, sync al iniciar sesión, capturas, minas, asedios).\n|cffffd100Importante:|r es el |cffffffffnúmero de ventana/pestaña de chat|r (General = 1, la siguiente que crees = 2, etc.). NO es una fila de canal personalizado como « 7.ov » en Ajustes > Canales: esa lista no tiene relación.\nElige 0 para el destino predeterminado de Blizzard, o crea primero una pestaña nueva y apunta a su rango (el deslizador muestra « N: NombrePestaña »)."
L.UI_FRONT_SELECT = "Frente de batalla (lista)"
L.UI_FRONT_PICKER_TOOLTIP = "Elige qué lista de zonas mostrar. Tu temporizador de captura y el combate siguen el mapa donde peleas."
L.UI_FRONT_READONLY = "No estás en este frente de batalla."
L.UI_FRONT_READONLY_SHORT = "Solo consulta"
L.UI_FRONT_READONLY_TOOLTIP = "Estás viendo otro frente o no estás en una zona de guerra. Los clics no inician capturas; los waypoints usan el mapa del frente seleccionado."
L.UI_STATUS_OFF_ZONE = "No estás en una zona de guerra"
L.UI_STATUS_VIEWING_FRONT = "Consulta: %s"
L.UI_CAPTURE_READONLY = "Solo lectura: ve a este frente en el mapa del mundo (Modo Guerra) para capturar desde esta lista."
L.NOTIFICATION_CHAT_DEFAULT_SHORT = "Predeterminado"
L.MAP_OVERLAY_OPACITY_LABEL   = "Opacidad de capturas (mapa)"
L.MAP_OVERLAY_OPACITY_TOOLTIP = "Transparencia de los círculos de captura en el |cffffffffmapa del mundo|r solamente. Valores más bajos dejan ver más detalle del mapa debajo.\nNo afecta a la minimapa (ver Opacidad de capturas (minimapa)) ni a los círculos de minas de coins."
L.MINIMAP_OVERLAY_OPACITY_LABEL   = "Opacidad de capturas (minimapa)"
L.MINIMAP_OVERLAY_OPACITY_TOOLTIP = "Transparencia de los círculos de captura en la |cffffffffminimapa|r. Valores más bajos dejan ver más detalle del mapa debajo.\nNo afecta al mapa del mundo, a los iconos de fortín ni a los círculos de minas de coins."
L.MINIMAP_BUTTON_LABEL          = "Botón del minimapa"
L.MINIMAP_BUTTON_TOOLTIP        = "Muestra el botón de Overlord alrededor del minimapa. Actívalo para recuperarlo; los gestores de botones del minimapa pueden guardarlo en su propio menú."
L.MINIMAP_CAPTURE_ZONES_LABEL   = "Zonas de captura (minimapa)"
L.MINIMAP_CAPTURE_ZONES_TOOLTIP = "Muestra círculos de captura coloreados en la |cffffffffminimapa|r. El ratón atraviesa los círculos para llegar al rastreo de cazador y comida (nombres al pasar). Desactiva para ocultarlos."
L.MAP_ZONE_TITLES_LABEL         = "Nombres de zonas (mapa)"
L.MAP_ZONE_TITLES_TOOLTIP       = "Muestra los carteles parchment con el nombre de zonas de captura, minas de coins y bosques en el |cffffffffmapa del mundo|r. Desactívalo para un mapa más limpio si ya conoces las zonas."
L.MAP_PATH_OPACITY_LABEL      = "Opacidad de rutas (mapa)"
L.MAP_PATH_OPACITY_TOOLTIP    = "Opacidad de las |cfffffffflíneas punteadas|r entre zonas de captura en el mapa del mundo (1 = tenue, 3 = muy visible)."
L.SETTINGS_TOGGLE_ON          = "Activado"
L.SETTINGS_TOGGLE_OFF         = "Desactivado"
L.AUTO_WAYPOINT_LABEL         = "Pin automático de objetivo"
L.AUTO_WAYPOINT_TOOLTIP       = "Coloca el pin de mapa de Blizzard en el próximo objetivo disponible. Si quitas o reemplazas ese pin, Overlord espera a un objetivo nuevo antes de colocarlo otra vez. El pin se retira cuando el objetivo deja de ser válido."
L.SHOW_TOP_HUD_LABEL          = "HUD superior"
L.SHOW_TOP_HUD_TOOLTIP        = "Auto muestra los paneles útiles cerca de capturas, minas, bosques y fortalezas. Siempre los muestra en los mapas pertinentes; Nunca los oculta. El indicador de objetivo sigue disponible."
L.TOP_HUD_MODE_AUTO           = "Auto"
L.TOP_HUD_MODE_ALWAYS         = "Siempre"
L.TOP_HUD_MODE_NEVER          = "Nunca"
L.SHOW_TUTORIAL_BOOK_LABEL    = "Icono libro tutorial"
L.SHOW_TUTORIAL_BOOK_TOOLTIP  = "Muestra el icono del libro tutorial en el HUD superior. Desactívalo para ocultar solo ese icono y conservar los paneles de coins, madera y fortaleza."
L.SOUND_ENABLED_LABEL         = "Sonidos de Overlord"
L.SOUND_ENABLED_TOOLTIP       = "Silencia todos los sonidos de Overlord (alertas, cuerno de guerra, capturas, paneles, buff de coins, música de duelo del general, etc.)."
L.SETTINGS_BUTTON             = "Opciones"
L.SETTINGS_BUTTON_TOOLTIP     = "Abre las opciones de Overlord."
L.SETTINGS_OPEN_UNAVAILABLE   = "Las opciones no están disponibles ahora. Usa Esc, luego Opciones, luego AddOns."
L.SCALE_CURRENT     = "Escala del panel: %.1f (rango de %.1f a %.1f)."
L.SCALE_SET         = "Escala del panel: %.1f."
L.ATTACK            = "¡Atacar!"
L.LOCKED            = "Bloqueada"
L.NEXT_OBJECTIVE_HEADER   = "Próximo objetivo"
L.NEXT_OBJECTIVE_BANNER     = "Próximo: %s"
L.NEXT_OBJECTIVE_TAG        = "SIGUIENTE"
L.NEXT_OBJECTIVE_GO         = "Ve aquí: permanece en la zona para iniciar el temporizador de captura."
L.GUIDE_BAR_LABEL           = "Guía"
L.GUIDE_BTN_TOOLTIP         = "Guía rápida (4 páginas)"
L.GUIDE_CLOSE               = "Cerrar"
L.GUIDE_TITLE               = "Guía"
L.GUIDE_PAGE_INDICATOR      = "Página %d / %d"
L.GUIDE_PREV                = "Anterior"
L.GUIDE_NEXT                = "Siguiente"
L.GUIDE_PAGE1_TITLE         = "Primeros pasos"
L.GUIDE_PAGE2_TITLE         = "Capturas y recursos"
L.GUIDE_PAGE3_TITLE         = "Fortalezas y puestos"
L.GUIDE_PAGE4_TITLE         = "Mando y clasificaciones"
L.GUIDE_SECTION_PANEL       = "El panel Overlord"
L.GUIDE_PANEL_BODY          = "Abre el |cFFFFD100|Haddon:Overlord:panel|hpanel Overlord|h|r con el botón del minimapa o el icono DataBroker.\n\n|cFFFFFFFFEn el panel|r\n• |cFFFFD100Dominación semanal|r: reparto de territorios entre Alianza y Horda esta semana.\n• |cFFFFD100Actividad reciente|r: combates registrados durante los últimos 5 minutos en cada frente y la Isla Serpenteante.\n• |cFFFFD100Acciones|r: Clasificación, Comunidad, Contratos, Exportar, Discord, Salón de la Fama, Guía, selector de frente, Llamada a las armas, Mando y Opciones.\n• |cFFFFD100Selector de frente|r: Arathi, Gilneas, Loch Modan, Los Baldíos del Sur, Durotar y Bosque de Elwynn.\n• |cFFFFD100Pestaña flecha|r (borde izquierdo): frente del día, zonas de control y contratos en curso.\n\n|cFFFFFFFFEn pantalla|r\n• HUD superior: coins, madera, fortaleza de hermandad (si aplica), flecha |cFFFFD100Próximo objetivo|r.\n• Icono del libro: reabre esta guía en cualquier momento."
L.GUIDE_SECTION_OPTIONS     = "Opciones útiles"
L.GUIDE_OPTIONS_BODY        = "Abre |cFFFFD100Opciones|r en el panel, o |cFFFFD100Esc → Complementos → Overlord|r.\n\n• |cFFFFD100Pin automático de objetivo|r: coloca el pin de mapa de Blizzard en el próximo objetivo (activado por defecto; espera si lo quitas).\n• |cFFFFD100HUD superior|r: oculta los paneles de coins, madera, guía y fortaleza de hermandad conservando el indicador |cFFFFD100Próximo objetivo|r.\n• |cFFFFD100Sonidos de Overlord|r: silencia alertas, cuerno de guerra, capturas y sonidos de paneles.\n• |cFFFFD100Overlays del mapa|r: ajusta la opacidad de capturas en el mapa del mundo y la minimapa, más la visibilidad de las líneas punteadas.\n• |cFFFFD100Escala del panel|r: tamaño del panel principal y la clasificación (o |cFFFFD100/ov scale|r).\n\nEscribe |cFFFFD100/ov guide|r en cualquier momento para reabrir esta guía."
L.GUIDE_SECTION_FEATURED    = "Frente del día"
L.GUIDE_FEATURED_BODY       = "Cada día de asedio, un frente está destacado. En ese frente con Modo Guerra, cada muerte con honor otorga |cFFFFD100+1 coin Overlord|r.\n\nEl panel lateral muestra el |cFFFFD100combate más reciente|r reportado en cada frente durante los últimos 5 minutos (datos de sincronización validados: kills, capturas, zonas bajo asalto).\n\nSi hay contratos de oro abiertos, también muestra el acceso directo |cFFFFD100Contratos en curso|r."
L.GUIDE_SECTION_CONTEST     = "Capturas disputadas"
L.GUIDE_CONTEST_BODY        = "Las zonas normales requieren |cFFFFD1002:00|r dentro del círculo de captura. Permanece en el círculo para avanzar el temporizador. Salir de la zona hace |cFFFF4444decae|r el progreso.\n\nLos enemigos dentro |cFFFF4444disputan|r la captura: igualdad congela el temporizador; superioridad enemiga lo hace retroceder hasta recuperar ventaja."
L.GUIDE_SECTION_HOF         = "Salón de la Fama"
L.GUIDE_HOF_BODY            = "|cFFFFD100Honores de hermandad y jugadores|r curados de los frentes (hazañas semanales, regimientos, stats de carrera, etc.).\n\nAcceso desde |cFFFFD100Acciones|r en el panel. Entradas seleccionadas a mano; no todos los honores aparecen en el mapa del mundo."
L.GUIDE_SECTION_TOOLS       = "Clasificaciones y sync"
L.GUIDE_TOOLS_BODY          = "• |cFFFFD100Clasificación|r: kills, capturas, fortalezas y puestos avanzados semanales de jugadores sincronizados.\n• |cFFFFD100Comunidad|r: únete a la comunidad Overlord para mejor sync e invitaciones.\n• |cFFFFD100Exportar|r: copia tus estadísticas para |cFFFFD100Check PvP|r.\n• |cFFFFD100Estadísticas|r: pestaña Overlord en la ficha de personaje.\n\nPermanece agrupado en el |cFFFFD100mismo shard|r para un estado fiable."
L.GUIDE_SECTION_TRAVEL      = "Cómo llegar"
L.GUIDE_TRAVEL_ALLIANCE     = "Activa el |cFFFFD100Modo Guerra|r (Talentos, tecla N). Obligatorio para Overlord."
L.GUIDE_TRAVEL_HORDE        = "Activa el |cFFFFD100Modo Guerra|r (Talentos, tecla N). Obligatorio para Overlord."
L.GUIDE_SECTION_SHARD       = "Shards y reinos"
L.GUIDE_SHARD_BODY          = "Los reinos |cFFFFD100Normal|r y |cFFFFD100Roleplay|r están en |cFFFFD100shards separados|r por defecto. No os veréis en el mundo abierto a menos que os faseéis juntos.\n\n|cFFFFFFFFPara la mejor experiencia|r\n• |cFFFFD100Formad grupo|r (banda o raid) con aliados en el |cFFFFD100mismo shard|r. El addon muestra tu ID de shard en la insignia del panel; haz clic para invitar a jugadores en otra capa."
L.GUIDE_SECTION_PROGRESS    = "Frentes de guerra"
L.GUIDE_PROGRESS_BODY       = "Seis |cFFFFD100frentes de guerra|r independientes: Arathi, Gilneas, Loch Modan, Los Baldíos del Sur, Durotar y Bosque de Elwynn. Cada uno tiene su árbol de zonas y capital de facción.\n\nLas zonas marcadas |cFFFFD100DISPONIBLE|r en el mapa se pueden atacar una vez cumplidos los prerrequisitos. Puede haber |cFFFFD100varias a la vez|r en ramas paralelas.\n\nEl HUD |cFFFFD100Próximo objetivo|r apunta a la zona más cercana. Consulta el mapa para otras opciones."
L.GUIDE_SECTION_GOLD        = "Minas de coins"
L.GUIDE_GOLD_BODY           = "Círculos de minas de coins en el mapa del mundo:\n%s\n\nModo Guerra obligatorio.\n\n|cFFFFFFFFCómo ganar coins|r\n• |cFFFFD100Pasivo|r: +1 coin cada 3 s dentro del círculo (tope 100).\n• |cFFFFD100Minería|r: +5 coins por cada veta minada dentro del círculo.\n\n|cFFFFFFFFGastar coins (25 coins)|r\n• |cFFFFD100Atacar|r: tu próxima captura de zona, capital, avanzada o fortaleza termina 60 s antes.\n• |cFFFFD100Reforzar|r: la próxima captura enemiga en tus zonas dura 60 s más.\n\nUn enemigo minando en tu mina alerta a toda tu facción."
L.GUIDE_SECTION_WOOD        = "Bosques"
L.GUIDE_WOOD_BODY           = "Círculos de bosque en el mapa del mundo:\n%s\n\nModo Guerra obligatorio.\n\n|cFFFFFFFFCómo ganar madera|r\n• |cFFFFD100Pasivo|r: +1 madera cada 15 s dentro del círculo (tope personal 500).\n• |cFFFFD100Reservas compartidas|r: cada bosque tiene reservas de facción (100); las reservas agotadas se reponen con el tiempo.\n\n|cFFFFFFFFGastar madera (250 madera)|r\n• |cFFFFD100Dominación +1 %|r: invierte madera personal para impulsar la dominación semanal de tu facción.\n\nLas reservas se sincronizan entre usuarios de Overlord."
L.GUIDE_SECTION_SIEGE       = "Asedio de capitales"
L.GUIDE_SIEGE_BODY          = "Las capitales enemigas usan un único temporizador de |cFFFFD1008:00|r (tu propia capital se recaptura en |cFFFFD1002:00|r como una zona normal).\n\n|cFFFFD100Tregua de 15 min|r tras una victoria total del frente (+2 %% de dominación semanal para el ganador)."
L.GUIDE_SECTION_OUTPOST     = "Puestos avanzados"
L.GUIDE_OUTPOST_BODY        = "Un |cFFFFD100puesto avanzado de hermandad|r por mapa de frente, más el puesto exterior temporal de la Isla Serpenteante (siempre abierto, a diferencia de las fortalezas).\n\n|cFFFFFFFFReglas|r\n• |cFFFFD100Modo Guerra|r y |cFFFFD100hermandad|r obligatorios para asaltar.\n• Mantén el cuadrado |cFFFFD1005 min|r; salir hace |cFFFF4444decaer|r el progreso.\n• Solo la |cFFFFD100facción enemiga|r puede disputar o reclamar.\n• Un asalto enemigo puede comenzar |cFFFFD100inmediatamente después de la captura|r.\n• Mientras esté en poder de una facción, las capturas enemigas de puntos normales de ese frente tardan |cFFFF444430 s más|r.\n• Permanece con su hermandad hasta una captura enemiga o el reinicio semanal.\n\nLas alertas de asalto y captura aparecen en el chat. El puesto se muestra en el mapa y en la clasificación."
L.GUIDE_SECTION_GENERAL     = "General de guerra"
L.GUIDE_GENERAL_BODY        = "El botón |cFFFFD100Mando|r (líder de grupo o banda, comunidad Overlord requerida) permite tomar la bandera. Tu icono aparece en el mapa de guerra para todos los aliados sincronizados.\n\nUn general por facción en el frente activo. Clic de nuevo para ceder el mando."
L.GUIDE_SECTION_BOUNTY      = "Recompensa de sangre"
L.GUIDE_BOUNTY_BODY         = "Alcanza |cFFFFD10010 kills|r sin morir en un frente y te conviertes en |cFFFFD100recompensa de sangre|r. Tu cráneo aparece en el mapa para los enemigos.\n\nReclamar una recompensa de sangre da |cFFFFD100+1 kill extra|r y |cFFFFD100+25 coins|r al cazador."
L.GUIDE_SECTION_GOLD_CONTRACT = "Contratos de oro"
L.GUIDE_GOLD_CONTRACT_BODY  = "Firma |cFFFFD100contratos de oro|r sobre jugadores enemigos con el botón |cFFFFD100Contratos|r del panel de guerra.\n\n|cFFFFFFFFFuncionamiento|r\n• Elige un enemigo conocido de tu |cFFFFD100grupo de reinos conectados|r o cualquier personaje enemigo de tus |cFFFFD100comunidades Overlord|r.\n• Debes estar en un |cFFFFD100frente de guerra activo|r para firmar un contrato.\n• Varios jugadores pueden ofrecer recompensas distintas sobre el mismo objetivo.\n• Cada golpe de gracia reclama solo la recompensa compatible más alta; las demás siguen abiertas.\n• El cazador que asesta el |cFFFFD100golpe de gracia|r en cualquier frente de guerra Overlord |cFFFFD100reclama|r el contrato automáticamente.\n\n|cFFFFFFFFPago|r\nEl oro |cFFFF4444no se reserva|r. Tras converger el claim, el firmante verifica y autoriza al ganador. El cazador aprobado envía una |cFFFFD100factura COD verificada|r con un objeto sin valor. El firmante la acepta manualmente en el buzón de Blizzard. El correo de oro directo sigue disponible como alternativa. Ambos personajes deben pertenecer al mismo grupo de reinos conectados.\n\n|cFFFFFFFFEn el mapa|r\nLos objetivos bajo contrato activo muestran un |cFFFFD100sello de cera|r en mapas de zona, continente y minimapa.\n\nUn jugador con contrato abierto sobre él no puede asumir el rol de |cFFFFD100General|r."
L.GUIDE_SECTION_FACTION_CALL = "Llamada de facción"
L.GUIDE_FACTION_CALL_BODY   = "El botón |cFFFFD100A las armas|r (en un frente activo, con enemigos cerca) alerta a los aliados en línea de tu |cFFFFD100comunidad Overlord|r. Enfriamiento compartido para toda la bandera."
L.VICTORY_DOMINATION_BONUS  = "Victoria total del frente: +%d %% de dominación semanal para tu facción."
L.GUIDE_SECTION_GUILD_KEEP  = "Fortaleza de hermandad"
L.GUIDE_GUILD_KEEP_BODY     = "Separado de los seis |cFFFFD100frentes de guerra|r (Arathi, Gilneas, Loch Modan, Los Baldíos del Sur, Durotar, Bosque de Elwynn): fortalezas de hermandad en |cFFFFD100Vallefresno|r, |cFFFFD100Los Humedales|r, |cFFFFD100Tierras Inhóspitas|r, |cFFFFD100El Cruce|r, |cFFFFD100Montañas Crestagrana|r y |cFFFFD100Mulgore|r.\n\n|cFFFFFFFFIconos de fortaleza|r\n%s\n\n|cFFFFFFFFReglas|r\n• |cFFFFD100Modo Guerra|r activo y |cFFFFD100hermandad|r obligatorios.\n• Las fortalezas son vulnerables cada 6 horas: |cFFFFD100%s|r.\n• Fuera de esta ventana, la captura está cerrada.\n\n|cFFFFFFFFCaptura|r\n• |cFFFFD100%d min|r dentro del cuadrado: al salir, el progreso |cFFFF4444decae|r.\n• Los enemigos en el cuadrado |cFFFF4444disputan|r la fortaleza: la igualdad congela el progreso, la superioridad enemiga lo hace retroceder.\n• Solo la |cFFFFD100facción enemiga|r puede disputar o reclamar la fortaleza.\n• El temporizador central solo aparece para los asaltantes de tu hermandad dentro del cuadrado.\n• Los |cFFFFD100kills en clasificación|r en una fortaleza solo cuentan durante la hora de asedio, dentro del cuadrado.\n• El progreso se sincroniza entre usuarios de Overlord (GK): permaneced agrupados.\n\n|cFFFFFFFFVictoria a las %s|r\n• Captura o defensa cuentan igual: |cFFFFD1001 victoria por asedio|r para esa fortaleza.\n• Una fortaleza mantenida sigue siendo vuestra hasta el reinicio semanal o una captura enemiga durante un asedio.\n• La clasificación solo muestra titular actual y victorias."
L.TOOLTIP_SHIFT_GUIDE       = "Mayús + clic izquierdo: guía rápida"

