L.GUIDE_PAGE4_TITLE         = "Kommando & Ranglisten"
L.GUIDE_SECTION_PANEL       = "Das Overlord-Panel"
L.GUIDE_PANEL_BODY          = "Öffnet das |cFFFFD100|Haddon:Overlord:panel|hOverlord-Panel|h|r über Minimap-Button oder DataBroker-Symbol.\n\n|cFFFFFFFFAm Panel|r\n• |cFFFFD100Wöchentliche Dominanz|r: Territoriumsanteil Allianz / Horde diese Woche.\n• |cFFFFD100Kürzliche Aktivität|r: Kämpfe der letzten 5 Minuten an jeder Front und auf der Gewundenen Insel.\n• |cFFFFD100Aktionen|r: Rangliste, Community, Verträge, Export, Discord, Ruhmeshalle, Anleitung, Frontwahl, Fraktionsruf, Kommando und Optionen.\n• |cFFFFD100Frontwahl|r: Arathi, Gilneas, Loch Modan, Südliches Brachland, Durotar und Wald von Elwynn.\n• |cFFFFD100Pfeilreiter|r (linker Rand): Front des Tages, Kontrollzonen und laufende Verträge.\n\n|cFFFFFFFFAm Bildschirm|r\n• HUD oben: Coins, Holz, Gildenfestung (falls zutreffend), |cFFFFD100Nächstes Ziel|r-Pfeil.\n• Buchsymbol: diese Anleitung jederzeit erneut öffnen."
L.GUIDE_SECTION_OPTIONS     = "Nützliche Optionen"
L.GUIDE_OPTIONS_BODY        = "Öffnet |cFFFFD100Einstellungen|r am Panel oder |cFFFFD100Esc → AddOns → Overlord|r.\n\n• |cFFFFD100Automatische Zielmarkierung|r: setzt die Blizzard-Kartenmarkierung auf das nächste Ziel (standardmäßig an; wartet, wenn Ihr sie entfernt).\n• |cFFFFD100Oberes HUD|r: blendet Coins-, Holz-, Anleitungs- und Gildenfestungs-Leiste aus, behält aber den |cFFFFD100Nächstes Ziel|r-Indikator.\n• |cFFFFD100Overlord-Töne|r: schaltet Alarme, Kriegshorn, Eroberungen und Panel-Töne stumm.\n• |cFFFFD100Karten-Overlays|r: Deckkraft der Eroberungen auf Weltkarte und Minimap sowie Sichtbarkeit der gestrichelten Verbindungslinien.\n• |cFFFFD100Panel-Skalierung|r: Größe von Hauptpanel und Rangliste (oder |cFFFFD100/ov scale|r).\n\nTippt |cFFFFD100/ov guide|r jederzeit, um diese Anleitung erneut zu öffnen."
L.GUIDE_SECTION_FEATURED    = "Front des Tages"
L.GUIDE_FEATURED_BODY       = "An jedem Belagerungstag ist ein Front hervorgehoben. Auf diesem Front im Kriegsmodus gewähren ehrenhafte Siege |cFFFFD100+1 Overlord-Coin|r.\n\nDas Seitenpanel zeigt den |cFFFFD100zuletzt gemeldeten Kampf|r an jeder Front während der letzten 5 Minuten (validierte Sync-Daten: Kills, Eroberungen, Zonen unter Angriff).\n\nBei offenen Goldverträgen erscheint dort auch die Verknüpfung |cFFFFD100Laufende Verträge|r."
L.GUIDE_SECTION_CONTEST     = "Umkämpfte Eroberungen"
L.GUIDE_CONTEST_BODY        = "Normale Zonen brauchen |cFFFFD1002:00|r im Eroberungskreis. Im Kreis bleiben, damit der Timer läuft. Verlassen der Zone lässt den Fortschritt |cFFFF4444sinken|r.\n\nFeinde im Kreis |cFFFF4444bekämpfen|r die Eroberung: Gleichstand pausiert den Timer; feindliche Überzahl lässt ihn zurückgehen, bis Ihr wieder im Vorteil seid."
L.GUIDE_SECTION_HOF         = "Ruhmeshalle"
L.GUIDE_HOF_BODY            = "Kuratierte |cFFFFD100Gilden- und Spielerehren|r von den Kriegsfronten (Wochenleistungen, Regimenter, Karriere-Stats usw.).\n\nÜber |cFFFFD100Aktionen|r am Panel. Einträge manuell ausgewählt; nicht jede Ehre erscheint auf der Weltkarte."
L.GUIDE_SECTION_TOOLS       = "Ranglisten & Sync"
L.GUIDE_TOOLS_BODY          = "• |cFFFFD100Rangliste|r: wöchentliche Kills, Eroberungen, Gildenfestungen und Außenposten synchronisierter Spieler.\n• |cFFFFD100Community|r: Overlord-Community für bessere Sync und Einladungen.\n• |cFFFFD100Export|r: Stats für |cFFFFD100Check PvP|r kopieren.\n• |cFFFFD100Statistik|r: Overlord-Tab im Charakterblatt.\n\nGruppiert auf dem |cFFFFD100selben Shard|r bleiben für zuverlässigen Zustand."
L.GUIDE_SECTION_TRAVEL      = "Anreise"
L.GUIDE_TRAVEL_ALLIANCE     = "Aktiviert den |cFFFFD100Kriegsmodus|r (Talente, Taste N). Pflicht für Overlord."
L.GUIDE_TRAVEL_HORDE        = "Aktiviert den |cFFFFD100Kriegsmodus|r (Talente, Taste N). Pflicht für Overlord."
L.GUIDE_SECTION_SHARD       = "Shards und Realms"
L.GUIDE_SHARD_BODY          = "|cFFFFD100Normal|r- und |cFFFFD100Rollenspiel|r-Realms liegen standardmäßig auf |cFFFFD100getrennten Shards|r. Ihr seht euch in der offenen Welt nicht, außer ihr phased zusammen.\n\n|cFFFFFFFFFür das beste Erlebnis|r\n• |cFFFFD100Gruppen|r (Gruppe oder Schlachtzug) mit Verbündeten auf dem |cFFFFD100selben Shard|r. Die Shard-ID steht am Panel-Abzeichen; Klick lädt Spieler auf anderer Layer ein."
L.GUIDE_SECTION_PROGRESS    = "Kriegsfronten"
L.GUIDE_PROGRESS_BODY       = "Sechs unabhängige |cFFFFD100Kriegsfronten|r: Arathi, Gilneas, Loch Modan, Südliches Brachland, Durotar und Wald von Elwynn. Jeder hat seinen Zonenbaum und seine Fraktionshauptstadt.\n\nZonen mit |cFFFFD100VERFÜGBAR|r auf der Karte könnt Ihr angreifen, wenn die Voraussetzungen erfüllt sind. Es kann |cFFFFD100mehrere parallel|r geben.\n\nDas HUD |cFFFFD100Nächstes Ziel|r zeigt die nächste Zone. Prüft die Karte für andere Optionen."
L.GUIDE_SECTION_GOLD        = "Coin-Minen"
L.GUIDE_GOLD_BODY           = "Coin-Minen-Kreise auf der Weltkarte:\n%s\n\nKriegsmodus nötig.\n\n|cFFFFFFFFCoins verdienen|r\n• |cFFFFD100Passiv|r: +1 Coin alle 3 s im Kreis (max. 100).\n• |cFFFFD100Abbau|r: +5 Coins pro Erz im Kreis.\n\n|cFFFFFFFFCoins ausgeben (25 Coins)|r\n• |cFFFFD100Angriff|r: Eure nächste Zonen-, Hauptstadt-, Außenposten- oder Gildenfestungs-Eroberung endet 60 s früher.\n• |cFFFFD100Verstärken|r: nächste feindliche Eroberung auf Euren Zonen dauert 60 s länger.\n\nFeindlicher Abbau in Eurer Mine alarmiert die ganze Fraktion."
L.GUIDE_SECTION_WOOD        = "Wälder"
L.GUIDE_WOOD_BODY           = "Waldkreise auf der Weltkarte:\n%s\n\nKriegsmodus nötig.\n\n|cFFFFFFFFHolz verdienen|r\n• |cFFFFD100Passiv|r: +1 Holz alle 15 s im Kreis (persönliches Maximum 500).\n• |cFFFFD100Gemeinsame Reserven|r: jeder Wald hat Fraktionsreserven (100); leere Reserven füllen sich mit der Zeit auf.\n\n|cFFFFFFFFHolz ausgeben (250 Holz)|r\n• |cFFFFD100Dominanz +1 %|r: persönliches Holz investieren, um die wöchentliche Fraktionsdominanz zu steigern.\n\nWaldbestände synchronisieren sich zwischen Overlord-Nutzern."
L.GUIDE_SECTION_SIEGE       = "Hauptstadt-Belagerung"
L.GUIDE_SIEGE_BODY          = "Feindliche Hauptstädte: |cFFFFD1008:00|r Timer (eigene Hauptstadt: |cFFFFD1002:00|r wie normale Zone).\n\n|cFFFFD10015 Min Waffenstillstand|r nach totalem Frontsieg (+2 %% wöchentliche Dominanz für den Sieger)."
L.GUIDE_SECTION_OUTPOST     = "Gilden-Außenposten"
L.GUIDE_OUTPOST_BODY        = "Ein |cFFFFD100Gilden-Außenposten|r pro Kriegsfront-Karte sowie der temporäre Außenposten in der offenen Welt auf der Gewundenen Insel (immer offen, anders als Gildenfestungen).\n\n|cFFFFFFFFRegeln|r\n• |cFFFFD100Kriegsmodus|r und |cFFFFD100Gilde|r nötig zum Angriff.\n• |cFFFFD1005 Min|r im Quadrat halten; Verlassen lässt den Fortschritt |cFFFF4444sinken|r.\n• Nur die |cFFFFD100feindliche Fraktion|r kann bekämpfen oder zurückerobern.\n• Ein feindlicher Angriff kann |cFFFFD100direkt nach der Eroberung|r beginnen.\n• Solange er gehalten wird, dauern gegnerische Eroberungen normaler Punkte an dieser Front |cFFFF444430 Sek. länger|r.\n• Er bleibt bis zu einer feindlichen Eroberung oder dem wöchentlichen Reset bei seiner Gilde.\n\nAngriffs- und Eroberungsmeldungen erscheinen im Chat. Der Außenposten ist auf der Weltkarte und in der Rangliste sichtbar."
L.GUIDE_SECTION_GENERAL     = "Kriegsgeneral"
L.GUIDE_GENERAL_BODY        = "Der Button |cFFFFD100Kommando|r (Gruppen- oder Schlachtzugleiter, Overlord-Community nötig) überträgt die Fahne. Euer Icon erscheint auf der Kriegskarte für alle synchronisierten Verbündeten.\n\nEin General pro Fraktion auf dem aktiven Front. Erneuter Klick gibt das Kommando ab."
L.GUIDE_SECTION_BOUNTY      = "Blutprämie"
L.GUIDE_BOUNTY_BODY         = "Erreicht |cFFFFD10010 Kills|r ohne zu sterben auf einem Front: Ihr werdet eine |cFFFFD100Blutprämie|r. Euer Totenkopf erscheint auf der Karte für Feinde.\n\nEine Blutprämie einzulösen gibt |cFFFFD100+1 Bonus-Kill|r und |cFFFFD100+25 Coins|r dem Jäger."
L.GUIDE_SECTION_GOLD_CONTRACT = "Goldverträge"
L.GUIDE_GOLD_CONTRACT_BODY  = "Unterzeichnet |cFFFFD100Goldverträge|r auf feindliche Spieler über den Button |cFFFFD100Verträge|r am Kriegspanel.\n\n|cFFFFFFFFAblauf|r\n• Wählt einen bekannten Feind aus Eurer |cFFFFD100Connected-Realm-Gruppe|r oder einen beliebigen feindlichen Charakter aus Euren |cFFFFD100Overlord-Communitys|r.\n• Ihr müsst auf einem |cFFFFD100aktiven Kriegsfront|r sein, um einen Vertrag zu unterzeichnen.\n• Mehrere Spieler können getrennte Belohnungen auf dasselbe Ziel setzen.\n• Jeder tödliche Schlag beansprucht nur die höchste kompatible Belohnung; die übrigen bleiben offen.\n• Der Jäger mit dem |cFFFFD100tötenden Schlag|r auf einer beliebigen Overlord-Kriegsfront |cFFFFD100beansprucht|r den Vertrag automatisch.\n\n|cFFFFFFFFZahlung|r\nGold wird |cFFFF4444nicht reserviert|r. Nach der Claim-Konvergenz prüft und autorisiert der Unterzeichner den Gewinner. Der freigegebene Jäger sendet eine |cFFFFD100geprüfte COD-Rechnung|r mit einem wertlosen Gegenstand. Der Unterzeichner nimmt sie manuell im Blizzard-Briefkasten an. Direkte Goldpost bleibt als Alternative verfügbar. Beide Charaktere müssen derselben Connected-Realm-Gruppe angehören.\n\n|cFFFFFFFFAuf der Karte|r\nAktive Vertragsziele zeigen ein |cFFFFD100Siegel|r auf Zonen-, Kontinent- und Minimap.\n\nEin Spieler mit offenem Vertrag kann nicht die Rolle |cFFFFD100General|r übernehmen."
L.GUIDE_SECTION_FACTION_CALL = "Fraktionsruf"
L.GUIDE_FACTION_CALL_BODY   = "Der Button |cFFFFD100Zu den Waffen|r (auf aktivem Front, mit Feinden in der Nähe) warnt online Verbündete in Eurer |cFFFFD100Overlord-Community|r. Geteilte Abklingzeit für die ganze Fraktionsfahne."
L.VICTORY_DOMINATION_BONUS  = "Totaler Frontsieg: +%d %% wöchentliche Dominanz für Eure Fraktion."
L.GUIDE_SECTION_GUILD_KEEP  = "Gildenfestung"
L.GUIDE_GUILD_KEEP_BODY     = "Getrennt von den sechs |cFFFFD100Kriegsfronten|r (Arathi, Gilneas, Loch Modan, Südliches Brachland, Durotar, Wald von Elwynn): Gildenfestungen in |cFFFFD100Eschental|r, |cFFFFD100Sumpfland|r, |cFFFFD100Ödland|r, |cFFFFD100Das Wegekreuz|r, |cFFFFD100Rotkammgebirge|r und |cFFFFD100Mulgore|r.\n\n|cFFFFFFFFFestungssymbole|r\n%s\n\n|cFFFFFFFFRegeln|r\n• |cFFFFD100Kriegsmodus|r aktiv und |cFFFFD100Gilde|r nötig.\n• Festungen sind alle 6 Stunden angreifbar: |cFFFFD100%s|r verwundbar.\n• Außerhalb dieses Fensters ist die Eroberung geschlossen.\n\n|cFFFFFFFFEroberung|r\n• |cFFFFD100%d Min|r im Quadrat; beim Verlassen |cFFFF4444sinkt|r der Fortschritt.\n• Feinde im Quadrat |cFFFF4444bekämpfen|r die Festung: Gleichstand pausiert den Fortschritt, feindliche Überzahl lässt ihn zurückgehen.\n• Nur die |cFFFFD100feindliche Fraktion|r kann bekämpfen oder zurückerobern.\n• Der zentrale Eroberungstimer erscheint nur für Angreifer Eurer Gilde im Quadrat.\n• |cFFFFD100Ranglisten-Kills|r auf einer Festung zählen nur während der Belagerungsstunde im Eroberungsquadrat.\n• Fortschritt sync zwischen Overlord-Nutzern (GK); gruppiert bleiben.\n\n|cFFFFFFFFSieg um %s|r\n• Eroberung oder Verteidigung zählen gleich: |cFFFFD1001 Sieg pro Belagerung|r für diese Festung.\n• Eine gehaltene Festung bleibt Eurer Gilde bis zum wöchentlichen Reset oder bis zu einer feindlichen Eroberung im Belagerungsfenster.\n• Die Rangliste zeigt nur aktuellen Halter und Siege."
L.TOOLTIP_SHIFT_GUIDE       = "Umschalt + Linksklick: Kurzanleitung"

