L.SHARD_ALERT_TAG              = " #%s"
L.SHARD_POPUP_EMPTY            = "Kein synchronisierter Addon-Spieler auf anderem Shard markiert."
L.SHARD_POPUP_ZONE_TITLE       = "Gegner auf anderem Shard"
L.SHARD_POPUP_ZONE_TITLE_ALLY  = "Verbündeter auf anderem Shard"
L.SHARD_POPUP_ZONE_SUB         = "%s: synchronisierte Spieler auf anderer Layer einladen, um sie auf euren Shard zu holen."
L.SHARD_POPUP_KEEP_ALREADY_CAPTURED_TITLE = "Keep bereits erobert (anderer Shard)"
L.SHARD_POPUP_KEEP_ALREADY_CAPTURED_SUB   = "%s wurde von %s um %s auf Shard %s erobert. Bittet einen Spieler dieses Shards, euch dorthin einzuladen."
L.SHARD_POPUP_KEEP_CONTEST_TITLE          = "Keep umkämpft (anderer Shard)"
