L.GUIDE_SECTION_PANEL       = "Панель Overlord"
L.GUIDE_PANEL_BODY          = "Откройте |cFFFFD100|Haddon:Overlord:panel|hпанель Overlord|h|r с помощью кнопки у мини-карты или иконки DataBroker.\n\n|cFFFFFFFFНа панели|r\n• |cFFFFD100Еженедельное господство|r: соотношение территорий между Альянсом и Ордой на этой неделе.\n• |cFFFFD100Действия|r: Таблица лидеров, Сообщество, Контракты, Экспорт, Discord, Зал славы, Обучение, выбор фронта, Призыв к оружию, Командование и Параметры.\n• |cFFFFD100Выбор фронта|r: Нагорье Арати, Гилнеас, Лок Модан, Южные Степи, Дуротар и Элвиннский лес.\n• |cFFFFD100Список зон|r: нажмите на |cFFFFD100ДОСТУПНУЮ|r зону для атаки; на карте отобразятся необходимые условия и круги захвата.\n• |cFFFFD100Вкладка со стрелкой|r (левый край): актуальный фронт дня, недавняя активность на всех фронтах и открытые контракты.\n\n|cFFFFFFFFНа экране|r\n• Верхний HUD: coins, древесина, крепость гильдии (если применимо), стрелка |cFFFFD100Следующей цели|r.\n• Иконка книги: позволяет повторно открыть это руководство в любое время."
L.GUIDE_SECTION_OPTIONS     = "Полезные параметры"
L.GUIDE_OPTIONS_BODY        = "Откройте |cFFFFD100Параметры|r на панели или перейдите в |cFFFFD100Escape → Параметры → Модификаторы → Overlord|r.\n\n• |cFFFFD100Автоматическая путевая точка|r: ставит стандартную булавку Blizzard на следующую цель (включено по умолчанию; ожидает, если вы её удалите).\n• |cFFFFD100Верхний HUD|r: скрывает панели coins, дерева, обучения и крепостей гильдий, сохраняя индикатор |cFFFFD100Следующей цели|r.\n• |cFFFFD100Звуки Overlord|r: отключает оповещения, боевой горн, звуки захвата и панели.\n• |cFFFFD100Слои карты|r: настраивает прозрачность захвата на карте мира и мини-карте, а также видимость линий путей.\n• |cFFFFD100Масштаб панели|r: изменяет размер главной панели и таблицы лидеров (или используйте команду |cFFFFD100/ov scale|r).\n\nВведите |cFFFFD100/ov guide|r в любое время, чтобы снова открыть это обучение."
L.GUIDE_SECTION_FEATURED    = "Актуальный фронт дня"
L.GUIDE_FEATURED_BODY       = "Каждый день осады один из фронтов становится актуальным. На этом фронте в режиме войны почётные победы приносят |cFFFFD100+1 coin Overlord|r.\n\nБоковая панель показывает |cFFFFD100недавние сражения|r, зафиксированные на всех фронтах за последние 5 минут (подтвержденные данные синхронизации: убийства, захваты, штурмуемые зоны).\n\nКогда доступны золотые контракты, там также отображается ярлык |cFFFFD100Открытые контракты|r."
L.GUIDE_SECTION_CONTEST     = "Оспариваемый захват"
L.GUIDE_CONTEST_BODY        = "Для обычных зон требуется находиться внутри круга захвата в течение |cFFFFD1002:00|r. Стойте в круге, чтобы продвигать таймер. Если вы покинете зону, прогресс начнет |cFFFF4444убывать|r.\n\nВражеские игроки внутри круга |cFFFF4444оспаривают|r захват: при равном количестве игроков таймер застывает; при численном преимуществе врага прогресс откатывается назад, пока вы снова не перехватите инициативу."
L.GUIDE_SECTION_HOF         = "Зал славы"
L.GUIDE_HOF_BODY            = "Особые |cFFFFD100заслуги гильдий и игроков|r на фронтах войны (еженедельные подвиги, дань уважения полкам, пожизненная статистика и т. д.).\n\nОткрыть его можно в меню |cFFFFD100Действия|r на панели. Записи подбираются вручную; не все почести отображаются на карте мира."
L.GUIDE_SECTION_TOOLS       = "Рейтинги и синхронизация"
L.GUIDE_TOOLS_BODY          = "• |cFFFFD100Таблица лидеров|r: еженедельные убийства, захваты, крепости гильдий и аванпосты синхронизированных игроков.\n• |cFFFFD100Сообщество|r: вступите в ряды сообщества Overlord для более надежной синхронизации и приглашений.\n• |cFFFFD100Экспорт|r: скопируйте свою статистику для |cFFFFD100Check PvP|r.\n• |cFFFFD100Статистика|r: дополнительная вкладка Overlord в окне вашего персонажа.\n\nОставайтесь в одной группе на |cFFFFD100одном фазовом слое (шарде)|r для стабильного обновления данных."
L.GUIDE_SECTION_TRAVEL      = "Как добраться"
L.GUIDE_TRAVEL_ALLIANCE     = "Включите |cFFFFD100Режим войны|r (Таланты, клавиша N). Требуется для работы Overlord."
L.GUIDE_TRAVEL_HORDE        = "Включите |cFFFFD100Режим войны|r (Таланты, клавиша N). Требуется для работы Overlord."
L.GUIDE_SECTION_SHARD       = "Фазирование и игровые миры"
L.GUIDE_SHARD_BODY          = "|cFFFFD100Обычные|r и |cFFFFD100RP (ролевые)|r игровые миры по умолчанию находятся на |cFFFFD100разных фазовых слоях (шардах)|r. Вы не увидите друг друга в открытом мире, пока не объединитесь в группу.\n\n|cFFFFFFFFДля наилучшего взаимодействия|r\n• |cFFFFD100Собирайтесь в группы|r (группу или рейд) с союзниками на |cFFFFD100одном слое|r. Модификатор показывает ID вашего шарда на значке панели; нажмите на него, чтобы пригласить игроков с другого слоя."
L.GUIDE_SECTION_PROGRESS    = "Фронты войны"
L.GUIDE_PROGRESS_BODY       = "Шесть независимых |cFFFFD100фронтов войны|r: Нагорье Арати, Гилнеас, Лок Модан, Южные Степи, Дуротар и Элвиннский лес. Каждый имеет свое дерево зон и столицу фракции.\n\nЗоны, отмеченные на карте как |cFFFFD100ДОСТУПНЫ|r, можно атаковать, как только выполнены их предварительные условия. На параллельных ветках может быть доступно |cFFFFD100несколько зон одновременно|r.\n\nИндикатор |cFFFFD100Следующая цель|r указывает на ближайшую зону. Проверьте карту на наличие других вариантов."
L.GUIDE_SECTION_GOLD        = "Рудники coins"
L.GUIDE_GOLD_BODY           = "Круги рудников coins на карте мира:\n%s\n\nТребуется Режим войны.\n\n|cFFFFFFFFКак зарабатывать coins|r\n• |cFFFFD100Пассивно|r: +1 coin каждые 3 сек., пока вы находитесь внутри круга (лимит 100).\n• |cFFFFD100Добыча руды|r: +5 coins за каждую добытую жилу внутри круга.\n\n|cFFFFFFFFНа что тратить coins (25 coins)|r\n• |cFFFFD100Атака|r: ваш следующий захват зоны, столицы, аванпоста или гильдейской крепости завершится на 60 сек. быстрее.\n• |cFFFFD100Укрепление|r: следующий захват врагом вашей зоны продлится на 60 сек. дольше.\n\nЕсли враг начнет добычу на вашем руднике, вся ваша фракция получит оповещение."
L.GUIDE_SECTION_WOOD        = "Леса"
L.GUIDE_WOOD_BODY           = "Круги лесов на карте мира:\n%s\n\nТребуется Режим войны.\n\n|cFFFFFFFFКак зарабатывать древесину|r\n• |cFFFFD100Пассивно|r: +1 древесина каждые 15 сек., пока вы находитесь внутри круга (личный лимит 500).\n• |cFFFFD100Общие запасы|r: каждый лес имеет запасы всей фракции (100); истощенные запасы со временем восполняются.\n\n|cFFFFFFFFНа что тратить древесину (250 древесины)|r\n• |cFFFFD100Господство +1%|r: вкладывайте личную древесину, чтобы увеличить еженедельное господство вашей фракции.\n\nЗапасы леса синхронизируются между пользователями Overlord."
L.GUIDE_SECTION_SIEGE       = "Осада столицы"
L.GUIDE_SIEGE_BODY          = "Для вражеских столиц используется один таймер захвата на |cFFFFD1008:00|r (ваша собственная столица отбивается за |cFFFFD1002:00|r, как обычная зона).\n\nПосле полной победы на фронте наступает |cFFFFD10015-минутное перемирие|r (+2% к еженедельному господству для победителя)."
L.GUIDE_SECTION_OUTPOST     = "Аванпосты гильдий"
L.GUIDE_OUTPOST_BODY        = "Один |cFFFFD100аванпост гильдии|r на каждой карте фронта (всегда открыт, в отличие от крепостей гильдий).\n\n|cFFFFFFFFПравила|r\n• Для штурма требуется |cFFFFD100Режим войны|r и нахождение в |cFFFFD100гильдии|r.\n• Удерживайте квадрат в течение |cFFFFD1005 мин.|r; если вы уйдете, прогресс начнет |cFFFF4444убывать|r.\n• Только |cFFFF4444вражеская фракция|r может оспорить или вернуть аванпост.\n• Вражеский штурм может начаться |cFFFFD100сразу после захвата|r.\n• Пока аванпост удерживается, захват обычных точек на этом фронте врагом длится на |cFFFF444430 сек. дольше|r.\n• Он остается за гильдией до тех пор, пока враг его не захватит или не произойдет еженедельный сброс.\n\nОповещения о штурме и захвате появляются в чате. Аванпост отображается на карте мира и отслеживается в таблице лидеров."
L.GUIDE_SECTION_GENERAL     = "Генерал войны"
L.GUIDE_GENERAL_BODY        = "Кнопка |cFFFFD100Командование|r (требуется быть лидером рейда или группы и состоять в сообществе Overlord) позволяет вам принять знамя. Ваша иконка появится на карте войны для всех синхронизированных союзников.\n\nОдин генерал на фракцию на активном фронте. Нажмите кнопку еще раз, чтобы сложить полномочия."
L.GUIDE_SECTION_BOUNTY      = "Охота за головами"
L.GUIDE_BOUNTY_BODY         = "Совершите |cFFFFD10010 убийств|r на фронте войны, не умирая, и вы станете целью для |cFFFFD100охоты за головами|r. Иконка черепа отобразится на карте для ваших врагов.\n\nУбийство такой цели приносит охотнику |cFFFFD100+1 бонусное убийство|r и |cFFFFD100+25 coins|r."
L.GUIDE_SECTION_GOLD_CONTRACT = "Золотые контракты"
L.GUIDE_GOLD_CONTRACT_BODY  = "Заключайте личные |cFFFFD100золотые контракты|r на вражеских игроков с помощью кнопки |cFFFFD100Контракты|r на панели войны.\n\n|cFFFFFFFFКак это работает|r\n• Выберите известного врага из вашей группы |cFFFFD100объединенных игровых миров|r или любого вражеского персонажа в ваших |cFFFFD100сообществах Overlord|r.\n• Вы должны находиться на |cFFFFD100активном фронте войны|r, чтобы подписать контракт.\n• Несколько игроков могут предложить раздельные награды за одну и ту же цель.\n• Смертельный удар забирает только самую высокую совместимую награду; остальные остаются открытыми.\n• Охотник, нанесший |cFFFFD100смертельный удар|r на любом фронте войны Overlord, автоматически |cFFFFD100получает|r контракт.\n\n|cFFFFFFFFОплата|r\nЗолото |cFFFF4444не резервируется|r. После подтверждения выполнения создатель контракта проверяет и утверждает победителя. Утвержденный охотник отправляет |cFFFFD100проверенное письмо с наложенным платежом (COD)|r с любым ненужным предметом. Создатель принимает его вручную в почтовом ящике Blizzard. Прямая отправка золота по почте остается доступной в качестве альтернативы. Охотник и создатель контракта должны принадлежать к одной группе объединенных игровых миров.\n\n|cFFFFFFFFНа карте|r\nЦели с активными контрактами отмечены |cFFFFD100сургучной печатью|r на картах зон, континентов и мини-карте.\n\nИгрок с открытым контрактом на его голову не может занять роль |cFFFFD100Генерала|r."
L.GUIDE_SECTION_FACTION_CALL = "Призыв фракции"
L.GUIDE_FACTION_CALL_BODY   = "Кнопка |cFFFFD100Призыв к оружию|r (на активном фронте, при наличии врагов поблизости) оповещает союзников в сети в вашем |cFFFFD100сообществе Overlord|r. Общее время восстановления для всего знамени фракции."
L.VICTORY_DOMINATION_BONUS  = "Полная победа на фронте: +%d%% к еженедельному господству вашей фракции."
L.GUIDE_SECTION_GUILD_KEEP  = "Крепость гильдии"
L.GUIDE_GUILD_KEEP_BODY     = "Отдельно от шести |cFFFFD100фронтов войны|r (Арати, Гилнеас, Лок Модан, Южные Степи, Дуротар, Элвиннский лес): крепости гильдий в |cFFFFD100Ясеневом лесу|r, |cFFFFD100Болотине|r, |cFFFFD100Бесплодных землях|r, на |cFFFFD100Перекрестке|r, в |cFFFFD100Красногорье|r и |cFFFFD100Мулгоре|r.\n\n|cFFFFFFFFИконки крепостей|r\n%s\n\n|cFFFFFFFFПравила|r\n• Требуется активный |cFFFFD100Режим войны|r и нахождение в |cFFFFD100гильдии|r.\n• Крепости уязвимы каждые 6 часов: |cFFFFD100%s|r.\n• Вне этого промежутка времени захват закрыт.\n\n|cFFFFFFFFЗахват|r\n• Находитесь |cFFFFD100%d мин.|r внутри квадрата: если вы покинете его, прогресс начнет |cFFFF4444убывать|r.\n• Враги в квадрате |cFFFF4444оспаривают|r крепость: равное количество игроков замораживает прогресс, численное преимущество врага откатывает его назад.\n• Только |cFFFFD100вражеская фракция|r может оспорить или вернуть крепость.\n• Центральный таймер захвата отображается только для штурмующих из вашей гильдии внутри квадрата.\n• |cFFFFD100Убийства для таблицы лидеров|r в крепости засчитываются только во время часа осады и только внутри квадрата захвата.\n• Прогресс синхронизируется между пользователями аддона (GK): оставайтесь в группе для более быстрого обновления данных.\n\n|cFFFFFFFFПобеда в %s|r\n• Захват или защита засчитываются одинаково: |cFFFFD1001 победа за осаду|r для этой крепости.\n• Удерживаемая крепость остается вашей до еженедельного сброса или пока вражеская гильдия не захватит ее во время осады.\n• В рейтинге отображаются только текущий владелец и победы в осадах."
L.TOOLTIP_SHIFT_GUIDE       = "Shift + ЛКМ: Краткое руководство"

